def fib_pivots(h: float, l: float) -> dict:
    rng = h - l
    fibs = (("1", 0.382), ("2", 0.618), ("3", 1.0))
    return {f"R{n}": h - rng * float(f) for n, f in fibs} | \
           {f"S{n}": l + rng * float(f) for n, f in fibs}

